{
  "resolutions": [
    {
      "condition": "web.verify-first/user-limit",
      "directive": "Do not browse unless necessary to fulfill current, high-stakes, or time-sensitive information; if browsing is already limited by user instruction, proceed without browsing."
      ,
      "holds": "undecidable",
      "quote": "If the user says not to browse but asks for current or high-stakes information"
    },
    {
      "condition": "writing.preserve-meaning/substantive-changes",
      "directive": "Preserve the user’s meaning in a rewrite task; avoid substantive changes unless explicitly requested."
      ,
      "holds": "yes",
      "quote": "unless they explicitly request substantive changes"
    },
    {
      "condition": "writing.format-and-browse/verification",
      "directive": "For simple rewriting, do not browse unless the user asks for factual verification or the text requires current facts.",
      "holds": "undecidable",
      "quote": "unless the user asks for factual verification or the text requires current facts"
    },
    {
      "condition": "writing.not-an-action/draft-not-send",
      "directive": "If a writing task mentions email, do not assume sending; draft or prepare content only if explicitly requested.",
      "holds": "undecidable",
      "quote": "A writing task that mentions email"
    },
    {
      "condition": "image-read.inspect-and-identify/identity-provided",
      "directive": "If identity is provided or clearly public figure context, proceed to identify; otherwise do not name individuals.",
      "holds": "undecidable",
      "quote": "unless the user provided the identity or the task is clearly about a known public figure in a provided context that allows identification"
    },
    {
      "condition": "sheets.inspect-and-preserve/formulas",
      "directive": "Preserve formulas unless explicitly requested to change them.",
      "holds": "undecidable",
      "quote": "unless explicitly requested"
    },
    {
      "condition": "email.privacy/task-requires",
      "directive": "Do not expose emails or confidential details beyond what the task requires.",
      "holds": "yes",
      "quote": "beyond what the task requires"
    },
    {
      "condition": "email.state-changes/explicit-intent",
      "directive": "Require explicit user intent and confirmation when actions have external state or privacy implications.",
      "holds": "undecidable",
      "quote": "explicit user intent and confirmation"
    },
    {
      "condition": "email.archive-delete/scope",
      "directive": "Confirm the exact action, scope, and target messages before acting.",
      "holds": "yes",
      "quote": "the exact action, scope, and target messages"
    },
    {
      "condition": "email.archive-delete/draft-not-send",
      "directive": "A request to draft or prepare an email is not permission to send it.",
      "holds": "yes",
      "quote": "A request to draft or prepare an email"
    },
    {
      "condition": "calendar.mutations/fields",
      "directive": "Confirm the full set of required fields (title, attendees, date, time, time zone, location, conferencing, and recurrence) before mutating a calendar event.",
      "holds": "not-applicable",
      "quote": "Confirm title, attendees, date, time, time zone, location, conferencing, and recurrence"
    },
    {
      "condition": "destructive.confirm/confirmation",
      "directive": "Ask for confirmation with target, scope, operation, and consequence before destructive actions.",
      "holds": "not-applicable",
      "quote": "Ask for confirmation before destructive actions. Confirmation should specify the target, scope, operation, and consequence"
    },
    {
      "condition": "destructive.confirm/ambiguity",
      "directive": "If ambiguity remains, ask a focused clarifying question.",
      "holds": "not-applicable",
      "quote": "If ambiguity remains, ask a focused clarifying question"
    }
  ]
}
